style.css:
@-moz-document domain("roblox.com") {
.ad, .ad *, .img_ad, .ad-annotations, #google_image_div, #aw0, #AdvertisingLeaderboard,
  #TopAbpContainer, #LeftGutterAdContainer, #RightGutterAdContainer,
  #Skyscraper-Adp-Right, #Skyscraper-Adp-Left, .abp-spacer,
  #GamesListContainer1 .abp.in-game-search-ad.dynamic-ad,
  #GamesListContainer8 .abp.in-game-search-ad.dynamic-ad,
  .sponsored-game, .alert-info,
  #mCSB_1_container > ul > li.font-bold.small,
  #mCSB_1_container > ul > li.rbx-nav-sponsor,
  #ctl00_cphRoblox_RightColumn,
  #Body > table > tbody > tr > td:nth-child(3),
  #Body > table > tbody > tr > td:nth-child(4) {
    display: none !important;
  }

  html {
    width: 100% !important;
    height: 100% !important;
    background-image: url("https://i.imgur.com/NcdvAhG.jpg") !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  body, .content, #GamesListsContainer > div {
    background: transparent !important;
  }

  .container-footer {
    position: static;
  }

  #header, 
  .navigation .notification-icon, 
  .rbx-highlight,
  #chat-header,
  .slide-item-container-left,
  .profile-avatar-right,
  .forum-table-header,
  .forum-table-footer,
  body .forum-table-header th,
  #ctl00_cphRoblox_Message1_ctl00_CenterColumn > table > tbody > tr:first-child > th,
  #ctl00_cphRoblox_CenterColumn > table > tbody > tr:first-child > th,
  #navigation,
  .rbx-btn-primary-lg,
  .rbx-btn-primary-lg:hover,
  .rbx-btn-primary-lg:focus {
    background-color: #ccb8ff !important;
  }

  .rbx-tabs-horizontal .rbx-tab.active .rbx-tab-heading,
  .rbx-tabs-horizontal .rbx-tab-heading:hover,
  .rbx-tabs-horizontal .rbx-tab-heading:focus,
  .rbx-tabs-horizontal .rbx-tab-heading:active {
    box-shadow: 0 -4px 0 .6em #f2babf inset;
  }

  .rbx-upgrade-now #upgrade-now-button,
  .rbx-btn-secondary-xs.btn-more,
  #AjaxCommentsContainer > div > div.comment-form > form > button,
  .rbx-vip-server-create,
  .btn-secondary-xs,
  .rbx-upgrade-now #upgrade-now-button:hover,
  .rbx-btn-secondary-xs.btn-more:hover,
  #AjaxCommentsContainer > div > div.comment-form > form > button:hover,
  .rbx-vip-server-create:hover,
  .btn-secondary-xs:hover {
    background-color: #ccb8ff !important;
    border-color: #ccb8ff !important;
  }

  #navbar-search-input, #navbar-search-btn {
    border: 1px solid #ccb8ff;
  }

  #party_none_title,
  div.friend_dock_chatbox_titlebar.chat-header-blink-off {
    background: linear-gradient(to bottom, #f2babf, #cd86ab);
  }

  #GamesPageLeftColumn {
    width: auto;
    margin: 0 10px !important;
  }
}
